```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology of securities, derivatives and related financial-market concepts, modelled from a corpus describing debt, equity, hybrid and derivative instruments." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled." .

fis:Asset a owl:Class ;
  rdfs:label "asset" ;
  rdfs:comment "A generic economic resource that can serve as the underlier of a derivative or as collateral; includes commodities, currencies, price indices, interest rates, loans, mortgages and financial instruments." .

fis:FinancialInstrument rdfs:subClassOf fis:Asset .

fis:CashInstrument a owl:Class ;
  rdfs:label "cash instrument" ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "An instrument whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:Derivative a owl:Class ;
  rdfs:label "derivative" ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "A financial contract between a buyer and seller whose value is derived from the value of one or more underlying assets, rates, indices or events. Every derivative involves an underlier, a future act, a price and a future date." .

owl:AllDisjointClasses [
  owl:members ( fis:CashInstrument fis:Derivative )
] .

fis:Security a owl:Class ;
  rdfs:label "security" ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A tradable financial asset; legal definitions vary by jurisdiction, but commonly include stocks, bonds, options and other negotiable, fungible investment instruments." .

fis:Loan a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument where borrower and lender must agree to any transfer, unlike a readily transferable security." .

fis:Deposit a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument such as a bank deposit, where transfer requires agreement between parties." .

#################################################################
# SECURITY BRANCH: DEBT / EQUITY / HYBRID / FUND / DEPOSITARY RECEIPT
#################################################################

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "debt security" ;
  rdfs:comment "A security under which the holder is entitled to payment of principal and interest; may be called a debenture, bond, deposit, note or commercial paper depending on maturity and collateral." .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "equity security" ;
  rdfs:comment "A share of equity interest in an entity, entitling the holder to a residual claim on the issuer's assets after creditors are paid, and generally to control and profit participation." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "A security combining characteristics of both debt and equity securities, e.g. preferred stock, convertible bonds, equity warrants." .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "depositary receipt" ;
  rdfs:comment "A negotiable instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local stock exchange." .

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "investment fund" ;
  rdfs:comment "An investment that pools money from many investors to purchase a portfolio of securities." .

owl:AllDisjointClasses [
  owl:members ( fis:DebtSecurity fis:EquitySecurity fis:HybridSecurity fis:DepositaryReceipt fis:InvestmentFund )
] .

#################################################################
# PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:comment "Relates a security to the entity issuing it." .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Investor ;
  rdfs:comment "Relates a security to an investor that holds it." .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ; rdfs:range fis:Asset ;
  rdfs:comment "Relates a derivative to the item (commodity, financial instrument, index, currency, interest rate) on whose performance its value depends." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:Derivative .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Asset ;
  rdfs:comment "Relates an asset-backed security or covered bond to the pool of assets backing its payments." .

fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ; rdfs:range fis:Security .

fis:hasConversionTarget a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:CommonStock ;
  rdfs:comment "Relates a convertible security to the common stock into which it may be converted." .

fis:isConversionTargetOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasConversionTarget ;
  rdfs:domain fis:CommonStock ; rdfs:range fis:Security .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer ;
  rdfs:comment "Relates a credit default swap to the debt issuer whose credit risk is referenced." .

fis:isReferenceEntityOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasReferenceEntity ;
  rdfs:domain fis:Issuer ; rdfs:range fis:CreditDefaultSwap .

fis:hasListing a owl:ObjectProperty ;
  rdfs:domain fis:StockExchange ; rdfs:range fis:Security ;
  rdfs:comment "Relates a stock exchange to a security listed on it." .

fis:isListingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasListing ;
  rdfs:domain fis:Security ; rdfs:range fis:StockExchange .

fis:hasPortfolio a owl:ObjectProperty ;
  rdfs:domain fis:InvestmentFund ; rdfs:range fis:Security ;
  rdfs:comment "Relates an investment fund to a security held in its portfolio." .

fis:isPortfolioOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasPortfolio ;
  rdfs:domain fis:Security ; rdfs:range fis:InvestmentFund .

fis:hasTrackedIndex a owl:ObjectProperty ;
  rdfs:domain fis:IndexFund ; rdfs:range fis:PriceIndex ;
  rdfs:comment "Relates an index fund to the market index whose performance it tracks." .

fis:isTrackedIndexOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasTrackedIndex ;
  rdfs:domain fis:PriceIndex ; rdfs:range fis:IndexFund .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:Stock ; rdfs:range fis:Dividend ;
  rdfs:comment "Relates a stock to a dividend distribution declared on it." .

fis:isDividendOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasDividend ;
  rdfs:domain fis:Dividend ; rdfs:range fis:Stock .

# Datatype properties

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date ;
  rdfs:comment "The date on which the issuer repays the principal; perpetual bonds have no maturity date." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate the issuer pays to the bondholder." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The nominal, principal or par amount of a bond, on which interest is calculated and which is repaid at maturity." .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string ;
  rdfs:comment "A grade assigned by a credit rating agency indicating credit quality, e.g. AAA or BB." .

fis:hasSeniorityLevel a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string ;
  rdfs:comment "Indicates whether a bond is 'senior' or 'subordinated' in priority of repayment." .

fis:hasRegistrationForm a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string ;
  rdfs:comment "Indicates whether a security is 'bearer', 'registered' or 'book-entry' in form." .

fis:hasDivisibility a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string ;
  rdfs:comment "Indicates whether a security is 'divided' (each instrument a separate asset) or 'undivided' (a fractional part of one whole issue)." .

fis:hasFungibility a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:comment "True if all holdings of the security are treated identically and are interchangeable." .

fis:hasCallFeature a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the issuer has the right to repay the bond before the maturity date." .

fis:hasPutFeature a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the holder has the right to force the issuer to repay the bond before the maturity date." .

fis:hasVotingRight a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the stock carries the right to vote in corporate decisions." .

fis:hasDividendPriority a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the stock has priority over common stock in the payment of dividends." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
  rdfs:comment "The fixed price at which the underlying may be bought or sold if the option is exercised." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date ;
  rdfs:comment "The last date on which an option may be exercised." .

fis:hasPremium a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
  rdfs:comment "The price paid by the option buyer to the option seller for the right conferred by the option." .

fis:hasOptionType a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
  rdfs:comment "Indicates whether an option is a 'call' (right to buy) or a 'put' (right to sell)." .

fis:hasExerciseStyle a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
  rdfs:comment "Indicates the exercise style of an option: 'American', 'European' or 'Bermudan'." .

fis:isStandardized a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:boolean ;
  rdfs:comment "True if the derivative contract is standardized and exchange-traded (as with futures), false if it is individually negotiated (as with forwards)." .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:date ;
  rdfs:comment "The specified future date at which a forward or future contract's transaction must take place." .

fis:hasDeliveryPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:decimal ;
  rdfs:comment "The price agreed upon today at which the underlying will be bought or sold on the delivery date." .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Swap ; rdfs:range xsd:decimal ;
  rdfs:comment "The principal amount over which swap cash flows are calculated; it is generally not exchanged between counterparties." .

fis:hasDividendAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Dividend ; rdfs:range xsd:decimal .

#################################################################
# ISSUERS AND INVESTORS
#################################################################

fis:Issuer a owl:Class ; rdfs:label "issuer" ;
  rdfs:comment "The company or other entity issuing a security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "A national government that issues sovereign (treasury) debt." .
fis:MunicipalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "A state, provincial, territorial or municipal governmental unit other than a sovereign government." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "An international organisation such as the World Bank or a regional development bank." .

owl:AllDisjointClasses [
  owl:members ( fis:Corporation fis:SovereignGovernment fis:MunicipalGovernment fis:SupranationalOrganization )
] .

fis:Investor a owl:Class ; rdfs:label "investor" ;
  rdfs:comment "A party that holds securities, either as a member of the public (retail) or as a financial institution (wholesale/institutional)." .

fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "A member of the public investing personally, other than by way of business." .

fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "A financial institution, such as an investment bank, insurance company, pension fund or mutual fund, acting on its own account or on behalf of clients." .

owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) ] .

fis:Shareholder a owl:Class ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Investor
      [ a owl:Restriction ; owl:onProperty fis:hasHolder ; owl:someValuesFrom fis:Stock ]
    )
  ] ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .

fis:Bondholder a owl:Class ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Investor
      [ a owl:Restriction ; owl:onProperty fis:hasHolder ; owl:someValuesFrom fis:Bond ]
    )
  ] ;
  rdfs:comment "The creditor to whom a bond issuer owes principal and interest." .

#################################################################
# MARKET INFRASTRUCTURE
#################################################################

fis:StockExchange a owl:Class ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .

fis:DerivativesExchange a owl:Class ;
  rdfs:comment "A market where standardized derivative contracts defined by the exchange are traded, acting as intermediary and taking margin from both sides." .

fis:ClearingHouse a owl:Class ;
  rdfs:comment "An entity that insures a futures or options contract and acts as intermediary mitigating counterparty default risk." .

fis:Dividend a owl:Class ;
  rdfs:comment "A portion of a company's profit paid to shareholders, which is discretionary and not a contractual obligation of the issuer." .

#################################################################
# DEBT SECURITY SUBCLASSES
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "A security under which the issuer owes the holder a debt, obliged to repay principal at maturity and usually to pay periodic interest (the coupon). Categorisations of bonds by issuer, coupon, optionality, maturity and form are not mutually exclusive." .

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A short-term debt instrument with original maturity of one year or less, highly liquid and sometimes called 'near cash'. Certificates of deposit and commercial paper are classified as money market instruments and not bonds." .

owl:AllDisjointClasses [ owl:members ( fis:Bond fis:MoneyMarketInstrument ) ] .

# --- Bond classified by issuer ---

fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "government bond" ;
  rdfs:comment "A bond issued by a sovereign national government to support public spending; also called a sovereign bond or treasury bond." .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:MunicipalGovernment ] ) ] ;
  rdfs:label "municipal bond" ;
  rdfs:comment "A bond issued by state or local governments, or entities they create, known in the US as a muni." .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:label "corporate bond" ;
  rdfs:comment "A bond issued by a corporation to raise financing. NOTE: one passage states the term sometimes also encompasses bonds issued by supranational organisations, conflicting with the strict issuer-based definition used here." .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
  rdfs:label "supranational bond" ;
  rdfs:comment "A bond issued by a supranational organisation such as the World Bank; also called a 'supra'." .

owl:AllDisjointClasses [
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:CorporateBond fis:SupranationalBond )
] .

# --- Bond classified by coupon structure ---

fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:label "zero-coupon bond" ;
  rdfs:comment "A bond, also called a discount bond, that pays no regular interest and is issued at a substantial discount to par value, with the full principal paid at maturity." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond whose coupon interest payment remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond (floater, FRN) whose coupon varies throughout its life based on a money-market reference rate such as LIBOR or SOFR." .

owl:AllDisjointClasses [
  owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond )
] .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond (linker) in which the principal amount and interest payments are indexed to the level of consumer prices." .

# --- Bond classified by optionality ---

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue true ] ) ] ;
  rdfs:comment "A bond giving the issuer the right to repay the bond before the maturity date." .

fis:PutableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue true ] ) ] ;
  rdfs:comment "A bond (retractable bond) giving the holder the right to force the issuer to repay before maturity." .

fis:ConvertibleBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "A bond that the holder can convert into a specified number of common shares of the issuer; a hybrid security with debt and equity features." .

# --- Bond classified by maturity ---

fis:PerpetualBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality 0 ] ) ] ;
  rdfs:comment "A bond (perpetuity, 'Perp') with no maturity date, where principal is repaid only at the discretion of the borrower." .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond that matures in installments over a period of time." .

# --- Bond classified by seniority ---

fis:SeniorBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniorityLevel ; owl:hasValue "senior" ] ) ] ;
  rdfs:comment "A bond holding priority in bankruptcy over other unsecured debt of the issuer." .

fis:SubordinatedBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniorityLevel ; owl:hasValue "subordinated" ] ) ] ;
  rdfs:comment "A bond with lower priority than senior bonds of the same issuer in case of liquidation." .

owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

# --- Security classified by registration form (applies to any security, incl. bonds) ---

fis:BearerSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "bearer" ] ) ] ;
  rdfs:comment "A security that entitles the holder to rights merely by holding it, transferred by delivery." .

fis:RegisteredSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "registered" ] ) ] ;
  rdfs:comment "A security that entitles the holder to rights only if recorded on a security register." .

fis:BookEntrySecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:hasValue "book-entry" ] ) ] ;
  rdfs:comment "A security with no paper certificate, existing only as an electronic record." .

owl:AllDisjointClasses [
  owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity )
] .

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
  rdfs:comment "A bearer security that is a bond; an official certificate issued without a named holder." .

fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .

fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BookEntrySecurity ) ] .

# --- Divisibility and fungibility of securities ---

fis:DividedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "divided" ] ) ] ;
  rdfs:comment "Each instrument constitutes a separate asset and a separate covenant of the issuer." .

fis:UndividedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "undivided" ] ) ] ;
  rdfs:comment "The entire issue makes up one single asset, with each security a fractional part of this undivided whole." .

owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue true ] ) ] ;
  rdfs:comment "A security in which all holdings are treated identically and are interchangeable." .

# --- Bond types defined by purpose/other features (subClassOf, non-exclusive) ---

fis:WarBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond issued by a government to fund military operations during wartime." .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond issued to raise finance for climate-change mitigation or adaptation projects." .

fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "A municipal bond guaranteeing repayment solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "A municipal bond whose principal and interest are secured by the full faith and credit of the issuer, supported by its taxing power." .

fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "An agreement for public sector entities to repay private investors after verified improved social outcomes." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond backed by cash flows from mortgages or public-sector assets that remain on the issuer's balance sheet, unlike an asset-backed security." ;
  owl:disjointWith fis:AssetBackedSecurity .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond (junk bond) rated below investment grade by credit rating agencies." .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond rated AAA, AA, A or BBB; also called high grade." .

owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

# --- Asset-backed securities ---

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:Asset .

fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] ;
  rdfs:label "asset-backed security" ;
  rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets such as loans, leases or receivables." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "mortgage-backed security" ;
  rdfs:comment "An asset-backed security secured by a mortgage or a pool of mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
  rdfs:comment "A pass-through MBS backed by mortgages on single-family, one- to four-unit residential property." .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
  rdfs:comment "A pass-through MBS backed by mortgages on commercial and multi-family properties." .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "A 'pay-through bond' debt obligation collateralized by mortgages, divided into tranches with different maturities and priorities." .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:label "collateralized debt obligation" ;
  rdfs:comment "A type of structured asset-backed security sliced into tranches that catch cash flow of interest and principal payments in sequence based on seniority." .

# --- Money market instruments ---

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity usually less than 270 days, sold at a discount from face value." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a fixed term before withdrawal without penalty." .

fis:TreasuryBill a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:comment "A short-term debt obligation of a national government, issued to mature in three to twelve months, sold at a discount." .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date. NOTE: one passage states repurchase agreements 'defy categorization' into the cash/derivative instrument matrix." .

#################################################################
# EQUITY SECURITY SUBCLASSES
#################################################################

fis:Stock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "stock" ;
  rdfs:comment "A share by which ownership of a corporation is divided; also called equity or capital stock." .

fis:CommonStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] ;
  rdfs:label "common stock" ;
  rdfs:comment "Stock that typically carries voting rights and the lowest priority to receive dividends and liquidation proceeds, also called ordinary share." .

fis:PreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:hasDividendPriority ; owl:hasValue true ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "preferred stock" ;
  rdfs:comment "Stock (preference share) that typically lacks voting rights but is entitled to dividends before common stock and to priority in liquidation; a hybrid of debt and equity features. CONFLICT NOTE: under IAS 32, a preference share that is mandatorily redeemable for cash, or redeemable at the holder's option, is classified as a financial liability rather than equity, even though it is commonly called 'preferred equity'." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Preferred stock that includes the ability of the holder to convert the preferred shares into a fixed number of common shares." .

#################################################################
# HYBRID SECURITY SUBCLASSES
#################################################################

fis:ConvertibleNote a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "A debt instrument used as a seed-investment vehicle that converts to equity in a future investing round." .

#################################################################
# DEPOSITARY RECEIPT SUBCLASSES
#################################################################

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "A depositary receipt listed and traded in the United States (ADR)." .

fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "A depositary receipt issued by European banks (EDR)." .

fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:comment "A depositary receipt issued by banks for global distribution (GDR)." .

owl:AllDisjointClasses [
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt )
] .

#################################################################
# INVESTMENT FUND SUBCLASSES
#################################################################

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "An open-end investment company that pools money from many investors and transacts at the fund's next-calculated net asset value." .

fis:ExchangeTradedFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
      [ a owl:Restriction ; owl:onProperty fis:hasListing ; owl:someValuesFrom fis:StockExchange ] ) ] ;
  rdfs:label "exchange-traded fund" ;
  rdfs:comment "An investment fund whose shares, unlike mutual fund shares, are bought and sold on national securities exchanges at market prices that may differ from net asset value." .

fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "An investment fund that pools investor money but, unlike a mutual fund, has few regulations protecting investors and uses more flexible, risky strategies." .

fis:IndexFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
      [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:PriceIndex ] ) ] ;
  rdfs:comment "A passively managed fund that tracks the performance of a market index." .

fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "A fund that seeks to outperform stock market indices through active security selection, generally charging higher fees than index funds." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:MoneyMarketFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
      [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] ;
  rdfs:comment "A mutual fund investing primarily in money market instruments." .

fis:BondFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
      [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:Bond ] ) ] ;
  rdfs:comment "A mutual fund investing primarily in bonds or other debt securities; also called an income fund." .

fis:StockFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
      [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:comment "A mutual fund investing primarily in stocks; also called an equity fund." .

#################################################################
# DERIVATIVE SUBCLASSES
#################################################################

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset .

fis:Forward a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
  rdfs:label "forward" ;
  rdfs:comment "A non-standardized, over-the-counter contract between two parties to buy or sell an asset at a specified future time at a price agreed upon today." .

fis:Future a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] ;
  rdfs:label "future" ;
  rdfs:comment "A standardized contract, written by a clearing house and traded on an exchange, to buy or sell an asset of standardized quantity and quality on a specified future date." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Option a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:label "option" ;
  rdfs:comment "A contract giving the holder the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date, in exchange for a premium paid to the seller." .

fis:CallOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] ;
  rdfs:comment "An option conveying the right to buy an asset at a fixed price." .

fis:PutOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] ;
  rdfs:comment "An option conveying the right to sell an asset at a fixed price." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
  rdfs:comment "An option that may be exercised at any time on or before expiration." .

fis:EuropeanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
  rdfs:comment "An option that may only be exercised on the expiry date." .

fis:BermudanOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
  rdfs:comment "An option that may be exercised only on specified dates on or before expiration." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An option whose payoff is determined by the average underlying price over a preset period." .

fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An option that requires the underlying's price to pass a certain barrier before it can be exercised." .

fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An all-or-nothing option that pays a fixed amount if a defined condition is met at expiration, otherwise nothing." .

fis:StockOption a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:comment "An option whose underlying asset is a stock." .

fis:Warrant a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "An option issued by the company itself allowing the holder to purchase a specific number of shares at a specified price within a specified time; unlike ordinary options, warrants are issued directly by the referenced company." .

fis:Swap a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:label "swap" ;
  rdfs:comment "A derivative in which two counterparties exchange cash flows ('legs') of one financial instrument for those of another, calculated over a notional principal amount that is usually not exchanged." .

fis:InterestRateSwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ] ) ] ;
  rdfs:comment "A swap in which counterparties exchange streams of interest payments, typically fixed for floating." .

fis:CurrencySwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] ;
  rdfs:comment "A swap in which counterparties exchange cash flows denominated in different currencies." .

fis:CreditDefaultSwap a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:label "credit default swap" ;
  rdfs:comment "A swap in which the seller compensates the buyer if the reference loan's debtor defaults or another credit event occurs, in exchange for periodic fee payments from the buyer." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

#################################################################
# IAS 32 / IFRS 9 CROSS-CUTTING ACCOUNTING CLASSIFICATION
#################################################################

fis:FinancialAsset a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial instrument, or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial instruments under potentially unfavourable conditions. CONFLICT NOTE: classification here depends on contractual substance, which can diverge from the market label of an instrument (e.g. mandatorily redeemable preferred stock)." .

fis:EquityInstrument a owl:Class ;
  rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities; conceptually aligned with fis:EquitySecurity." .

fis:AmortizedCostFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "IFRS 9: a financial asset held to collect contractual cash flows that are solely payments of principal and interest, measured at amortised cost." .

fis:FairValueThroughOtherComprehensiveIncomeFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "IFRS 9 (FVOCI): a financial asset held both to collect contractual cash flows and to sell, meeting the solely-payments-of-principal-and-interest test." .

fis:FairValueThroughProfitOrLossFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "IFRS 9 (FVTPL): a financial asset not qualifying for amortised cost or FVOCI, including all derivative financial assets and, by default, equity investments." .

owl:AllDisjointClasses [
  owl:members ( fis:AmortizedCostFinancialAsset
                fis:FairValueThroughOtherComprehensiveIncomeFinancialAsset
                fis:FairValueThroughProfitOrLossFinancialAsset )
] .

fis:Derivative rdfs:subClassOf fis:FairValueThroughProfitOrLossFinancialAsset .
