```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "Models financial instruments, securities (debt, equity, hybrid, derivative), funds, issuers and related classification axes, as described in the supplied corpus." .

#################################################################
# TOP-LEVEL FINANCIAL INSTRUMENT HIERARCHY
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled (IAS 32/39: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Cash Instrument" ;
  rdfs:comment "An instrument whose value is determined directly by the markets; includes securities, loans and deposits." .

fis:DerivativeInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Derivative" ;
  rdfs:comment "A contract whose value is derived from the performance of an underlying asset, index, rate or event." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CashInstrument fis:DerivativeInstrument ) .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "Cash instrument requiring agreement between borrower and lender to transfer; not readily transferable like a security." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Security" ;
  rdfs:comment "A tradable financial asset, readily transferable, negotiable and fungible. NOTE: the US SEC definition broadly classifies derivatives (forwards, futures, options, swaps) as a kind of security, which conflicts with the 'cash instrument vs derivative instrument' split used elsewhere in the corpus. This ontology follows the majority structural framing (Security subClassOf CashInstrument, disjoint from DerivativeInstrument) and records the conflict here." .

#################################################################
# SECURITY TOP PARTITION: DEBT / EQUITY / HYBRID
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:label "Debt Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ]
  ) ] ;
  rdfs:comment "Holder is entitled to payment of principal and interest; holder is a creditor of the issuer." .

fis:EquitySecurity a owl:Class ;
  rdfs:label "Equity Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality 0 ]
  ) ] ;
  rdfs:comment "Share of ownership interest in an entity; equity has no maturity date and entitles holder to a residual claim after creditors are paid." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Hybrid Security" ;
  rdfs:comment "Combines some characteristics of both debt and equity securities (e.g. preferred stock, convertible bonds, equity warrants). Not disjoint with DebtSecurity, since e.g. convertible bonds are both." .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity ) .

#################################################################
# CLASSIFICATION AXES OF SECURITIES (ownership/transfer form)
#################################################################

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Entitles holder to rights merely by possession; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Entitles holder to rights only if registered on a security register." .
fis:BookEntrySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Non-certificated, electronic (dematerialized) security." .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each instrument constitutes a separate, legally distinct asset/covenant." .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue is one single asset; each security is a fractional part of the whole." .
[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "All holdings treated identically and interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Not interchangeable with other securities of the same issuer (e.g. different bond series)." .
[] a owl:AllDisjointClasses ; owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) .

#################################################################
# ISSUERS
#################################################################

fis:Issuer a owl:Class ; rdfs:label "Issuer" ;
  rdfs:comment "The entity which is obligated on, or which issues, a security or financial instrument." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "Sub-sovereign governmental unit: state, provincial, territorial, municipal." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Corporation .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation ) .

fis:CreditRating a owl:Class ; rdfs:label "Credit Rating" .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating .
fis:BelowInvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating .
[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeRating fis:BelowInvestmentGradeRating ) .

#################################################################
# HOLDERS / INVESTORS
#################################################################

fis:Holder a owl:Class ; rdfs:label "Holder" .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "Owner of one or more shares of stock." .
fis:Investor a owl:Class ; rdfs:subClassOf fis:Holder .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Member of the public investing personally, other than by way of business." .
fis:WholesaleInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Financial institution acting on its own account or on behalf of clients." .
[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:WholesaleInvestor ) .

#################################################################
# GENERIC UNDERLYING-ASSET CLASSES
#################################################################

fis:Asset a owl:Class ; rdfs:label "Asset" ;
  rdfs:comment "Generic class usable as range of hasUnderlying / hasCollateral." .
fis:FinancialInstrument rdfs:subClassOf fis:Asset .
fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "Interest Rate Benchmark" ;
  rdfs:comment "e.g. LIBOR, SOFR, Euribor." .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Asset .
fis:StockMarketIndex a owl:Class ; rdfs:subClassOf fis:PriceIndex .

fis:AssetPool a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "A discrete or revolving pool of financial assets used as collateral for asset-backed securities." .
fis:MortgagePool a owl:Class ; rdfs:subClassOf fis:AssetPool .
fis:ResidentialMortgagePool a owl:Class ; rdfs:subClassOf fis:MortgagePool .
fis:CommercialMortgagePool a owl:Class ; rdfs:subClassOf fis:MortgagePool .
fis:DebtObligationPool a owl:Class ; rdfs:subClassOf fis:AssetPool .
fis:AutoLoanPool a owl:Class ; rdfs:subClassOf fis:AssetPool .
fis:CreditCardReceivablePool a owl:Class ; rdfs:subClassOf fis:AssetPool .
fis:StudentLoanPool a owl:Class ; rdfs:subClassOf fis:AssetPool .
fis:HomeEquityLoanPool a owl:Class ; rdfs:subClassOf fis:AssetPool .

fis:RepaymentSource a owl:Class .
fis:TaxingPower a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
fis:SpecificRevenueStream a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
[] a owl:AllDisjointClasses ; owl:members ( fis:TaxingPower fis:SpecificRevenueStream ) .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the security." .
fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Asset ;
  rdfs:comment "The underlier (asset, index, currency, interest rate or other instrument) upon which a derivative or convertible instrument's value is based." .
fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Holder .
fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ; rdfs:range fis:Security .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:Asset ;
  rdfs:comment "Asset or asset pool backing a debt security." .
fis:isCollateralOf a owl:ObjectProperty ; owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ; rdfs:range fis:DebtSecurity .

fis:hasEmbeddedOption a owl:ObjectProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:Option .

fis:hasPortfolioHolding a owl:ObjectProperty ;
  rdfs:domain fis:Fund ; rdfs:range fis:FinancialInstrument .

fis:hasCreditRatingValue a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:CreditRating .

fis:hasReferenceRate a owl:ObjectProperty ;
  rdfs:domain fis:FloatingRateNote ; rdfs:range fis:InterestRateBenchmark .

fis:hasIndexReference a owl:ObjectProperty ;
  rdfs:domain fis:InflationIndexedBond ; rdfs:range fis:PriceIndex .

fis:hasTradingVenue a owl:ObjectProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range fis:TradingVenue .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range fis:Dividend .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer .

fis:hasReferenceObligation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:DebtSecurity .

fis:hasTrackedIndex a owl:ObjectProperty ;
  rdfs:domain fis:IndexFund ; rdfs:range fis:PriceIndex .

fis:hasRepaymentSource a owl:ObjectProperty ;
  rdfs:domain fis:MunicipalBond ; rdfs:range fis:RepaymentSource .

fis:hasOffering a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:SecurityOffering .

fis:hasAssociatedFinancialAsset a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:FinancialAsset .
fis:hasAssociatedFinancialLiability a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:FinancialLiability .
fis:hasAccountingMeasurement a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:AccountingMeasurementCategory .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "face value" ;
  rdfs:comment "Also called nominal, principal or par amount." .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date .

fis:hasIssueDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:date .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasTermInDays a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:integer .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date .

fis:hasPremium a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:date ;
  rdfs:comment "Used by Forward and Future contracts." .

fis:hasDeliveryPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Forward ; rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Swap ; rdfs:range xsd:decimal .

fis:hasMarketCapitalization a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:decimal .

fis:hasCurrencyDenomination a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:passesPrincipalAndInterestTest a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range xsd:boolean ;
  rdfs:comment "IFRS 9 'solely payments of principal and interest' (SPPI) test used in business-model classification." .

#################################################################
# BONDS
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Bond" ;
  rdfs:comment "Issuer owes holder a debt and is obliged to repay principal at maturity and usually to pay interest (coupon)." .

fis:Debenture a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:maxCardinality 0 ]
  ) ] ;
  rdfs:comment "Unsecured bond with only a general claim on the issuer's assets." .

fis:SecuredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ]
  ) ] .
[] a owl:AllDisjointClasses ; owl:members ( fis:Debenture fis:SecuredBond ) .

fis:Note a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Debt security with shorter maturity than a debenture." .

fis:Eurobond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued internationally outside the domestic market, underwritten and unsecured, interest paid gross." .

fis:SeniorDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Contractually senior; holders have priority in bankruptcy." .
fis:SubordinatedDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Debt that is not senior." .
[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorDebtSecurity fis:SubordinatedDebtSecurity ) .

### Bond classification by issuer

fis:GovernmentBond a owl:Class ;
  rdfs:label "Government Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
  ) ] .

fis:MunicipalBond a owl:Class ;
  rdfs:label "Municipal Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
  ) ] .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
  ) ] .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
  ) ] ;
  rdfs:comment "Strictly, excludes municipal and most supranational bonds, though the term sometimes extends to supranational issuers." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) .

fis:GeneralObligationBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MunicipalBond [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:TaxingPower ]
  ) ] .
fis:RevenueBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MunicipalBond [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:SpecificRevenueStream ]
  ) ] ;
  rdfs:comment "Typically non-recourse; repayment solely from a specified revenue-generating entity." .
[] a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued to raise finance for climate mitigation/adaptation projects." .

fis:HighYieldBond a owl:Class ;
  rdfs:label "High-Yield Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingValue ; owl:someValuesFrom fis:BelowInvestmentGradeRating ]
  ) ] ;
  rdfs:comment "Also called junk bond." .

### Bond classification by coupon/maturity features

fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ]
  ) ] ;
  rdfs:comment "Pays no periodic interest; sold at a discount to par, redeemed at face value at maturity." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasReferenceRate ; owl:someValuesFrom fis:InterestRateBenchmark ]
  ) ] .

fis:PerpetualBond a owl:Class ;
  rdfs:label "Perpetual Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality 0 ]
  ) ] ;
  rdfs:comment "Has no maturity date; also called a perpetuity or 'Perp'." .

fis:InflationIndexedBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIndexReference ; owl:someValuesFrom fis:PriceIndex ]
  ) ] .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

fis:ConvertibleBond a owl:Class ;
  rdfs:label "Convertible Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond fis:HybridSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
  ) ] ;
  rdfs:comment "Can be converted, at holder's election, into the ordinary shares of the issuing company." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Exchangeable into shares of a corporation other than the issuer." .

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ]
  ) ] .

fis:PutableBond a owl:Class ;
  rdfs:label "Putable Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ]
  ) ] ;
  rdfs:comment "Also called a retractable bond." .

fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BookEntrySecurity ) ] .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ;
  rdfs:label "Money Market Instrument" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:DebtSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasTermInDays ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                            owl:withRestrictions ( [ xsd:maxInclusive 365 ] ) ] ]
  ) ] ;
  rdfs:comment "Short-term debt instrument with original maturity of one year or less; highly liquid, 'near cash'." .

fis:CommercialPaper a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MoneyMarketInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasTermInDays ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                            owl:withRestrictions ( [ xsd:maxInclusive 270 ] ) ] ]
  ) ] ;
  rdfs:comment "Unsecured promissory note with fixed maturity of usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Time deposit sold by banks, thrifts and credit unions." .

fis:TreasuryBill a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MoneyMarketInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
  ) ] ;
  rdfs:comment "Short-term zero-coupon government debt obligation maturing in three to twelve months." .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
  rdfs:label "Asset-Backed Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:DebtSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:AssetPool ]
  ) ] ;
  rdfs:comment "Structured security backed by a pool of assets; umbrella term also sometimes restricted to consumer-loan-backed securities as distinct from MBS and CDO." .

fis:MortgageBackedSecurity a owl:Class ;
  rdfs:label "Mortgage-Backed Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:MortgagePool ]
  ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MortgageBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgagePool ]
  ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MortgageBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgagePool ]
  ) ] .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Also called a 'pay-through bond'; divided into tranches with different maturities and priorities." .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligationPool ]
  ) ] ;
  rdfs:comment "Sliced into tranches catching cash flows in sequence based on seniority." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets which, unlike ABS, remain on the issuer's balance sheet." .

fis:AutoLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:AutoLoanPool ]
  ) ] .
fis:CreditCardBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CreditCardReceivablePool ]
  ) ] .
fis:StudentLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:StudentLoanPool ]
  ) ] .
fis:HomeEquityLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:HomeEquityLoanPool ]
  ) ] .

#################################################################
# STOCK / EQUITY
#################################################################

fis:Stock a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Stock" ;
  rdfs:comment "Also called capital stock or (in UK/Commonwealth usage) share; consists of all shares by which ownership of a company is divided." .

fis:CommonStock a owl:Class ;
  rdfs:subClassOf fis:Stock, fis:EquitySecurity ;
  rdfs:label "Common Stock" ;
  rdfs:comment "Also called ordinary share or voting share; typically carries voting rights." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  rdfs:label "Preferred Stock" ;
  rdfs:comment "Also called preference shares; hybrid of debt and equity, senior to common stock but subordinate to bonds. CONFLICT: the corpus's 'equity security' passage also calls preferred equity 'a form of capital stock' (treating it as equity), while the 'hybrid securities' passage frames it as an intermediate class between equity and debt; this ontology follows the majority (hybrid) framing. Under IAS 32, a mandatorily redeemable preference share is additionally classified as a FinancialLiability rather than equity, a further classification divergence." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:PreferredStock [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
  ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common dividends resume." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Also called straight preferred; passed dividends are lost." .
[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:HybridSecurity [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
  ) ] ;
  rdfs:comment "Option issued by the company allowing the holder to purchase shares at a specified price within a specified time." .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "Negotiable instrument issued by a bank representing a foreign company's publicly traded securities." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

fis:Dividend a owl:Class ; rdfs:label "Dividend" ;
  rdfs:comment "A discretionary portion of a company's profit paid to shareholders, unlike a bond's contractual coupon." .
fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
[] a owl:AllDisjointClasses ; owl:members ( fis:CashDividend fis:StockDividend ) .

#################################################################
# FUNDS
#################################################################

fis:Fund a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "Fund" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:FinancialInstrument ]
  ) ] ;
  rdfs:comment "Pools money from many investors to purchase a portfolio of securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:Fund .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "Shares trade on exchanges at market prices that may deviate from net asset value, unlike mutual funds which transact only at NAV." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "Pools investor money but with fewer regulatory protections and more flexible/risky strategies than mutual funds." .
fis:MoneyMarketFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Fund [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:MoneyMarketInstrument ]
  ) ] .
fis:BondFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Fund [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:DebtSecurity ]
  ) ] .
fis:EquityFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Fund [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:EquitySecurity ]
  ) ] .
fis:IndexFund a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Fund [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:PriceIndex ]
  ) ] ;
  rdfs:comment "Passively managed fund that tracks the performance of an index." .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:comment "Purchased from/sold to the issuer at NAV; new units created on demand." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:Fund .
[] a owl:AllDisjointClasses ; owl:members ( fis:OpenEndFund fis:ClosedEndFund ) .

#################################################################
# DERIVATIVES
#################################################################

fis:TradingVenue a owl:Class .
fis:Exchange a owl:Class ; rdfs:subClassOf fis:TradingVenue .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:TradingVenue .
[] a owl:AllDisjointClasses ; owl:members ( fis:Exchange fis:OverTheCounterMarket ) .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Standardized derivative traded via a specialized derivatives exchange." .
fis:OverTheCounterDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Privately negotiated derivative traded directly between two parties without an exchange." .
[] a owl:AllDisjointClasses ; owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) .

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Obligates contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under specified terms." .
[] a owl:AllDisjointClasses ; owl:members ( fis:LockProduct fis:OptionProduct ) .

fis:Forward a owl:Class ;
  rdfs:subClassOf fis:LockProduct, fis:OverTheCounterDerivative ;
  rdfs:label "Forward" ;
  rdfs:comment "Non-standardized, tailored contract between two parties to buy/sell an asset at a specified future time at today's pre-determined price." .

fis:Future a owl:Class ;
  rdfs:subClassOf fis:LockProduct, fis:ExchangeTradedDerivative ;
  rdfs:label "Future" ;
  rdfs:comment "Standardized contract, written by a clearing house, to buy or sell an asset on a future date at a price specified today." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Forward fis:Future ) .

fis:Option a owl:Class ;
  rdfs:subClassOf fis:OptionProduct ;
  rdfs:label "Option" ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Right to buy the underlying at the strike price." .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
